CREATE OR REPLACE FUNCTION public.indicadores_checkin(_metric_id uuid,_value numeric,_confidence text,_comment text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.indicadores_metrics; result uuid; BEGIN SELECT * INTO m FROM public.indicadores_metrics WHERE id=_metric_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR NOT coalesce(public.indicadores_metric_visible(_metric_id),false) OR (m.responsible_id IS DISTINCT FROM auth.uid() AND public.indicadores_role(auth.uid()) IS DISTINCT FROM 'admin') THEN RAISE EXCEPTION 'Sem permissão para atualizar este indicador.'; END IF; IF m.objective_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.indicadores_objectives o JOIN public.indicadores_cycles c ON c.id=o.cycle_id WHERE o.id=m.objective_id AND c.archived) THEN RAISE EXCEPTION 'O ciclo está arquivado.'; END IF; IF _confidence IS NULL OR _confidence NOT IN ('on_track','at_risk','late') OR _value IS NULL OR (m.measure='binary' AND _value NOT IN (0,1)) THEN RAISE EXCEPTION 'Valor ou confiança inválidos.'; END IF; INSERT INTO public.indicadores_checkins(metric_id,value,confidence,comment,recorded_by) VALUES(_metric_id,_value,_confidence,coalesce(_comment,''),auth.uid()) RETURNING id INTO result; UPDATE public.indicadores_metrics SET current_value=_value,confidence=_confidence WHERE id=_metric_id; RETURN result; END $$; REVOKE ALL ON FUNCTION public.indicadores_checkin(uuid,numeric,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.indicadores_checkin(uuid,numeric,text,text) TO authenticated,service_role;